actions.script:
if (clearParent) ec.service.sync().name('update#mantle.work.effort.WorkEffort').parameters({workEffortId: workEffortId, parentWorkEffortId: null}).call()
const subtree = [workEffortId]
for (let i = 0; i < subtree.length && i < 100000; i++) {
    for (const child of ec.entity.find('mantle.work.effort.WorkEffort').condition('parentWorkEffortId', subtree[i]).selectField('workEffortId').list()) {
        if (subtree.includes(child.workEffortId)) continue
        subtree.push(child.workEffortId)
        ec.service.sync().name('update#mantle.work.effort.WorkEffort').parameters({workEffortId: child.workEffortId, rootWorkEffortId: rootWorkEffortId}).call()
    }
}
for (const assoc of ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('toWorkEffortId', 'in', subtree)
        .condition('workEffortAssocTypeEnumId', 'in', ['WeatMilestone', 'WeatRelease', 'WeatSprint', 'WeatComponent'])
        .conditionDate('fromDate', 'thruDate', null).list()) {
    const plan = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', assoc.workEffortId).one()
    if (plan?.rootWorkEffortId === rootWorkEffortId) continue
    assoc.set('thruDate', ec.user.nowTimestamp)
    assoc.update()
}

const kinds = {WeatMilestone: 'WetMilestone', WeatRelease: 'WetRelease', WeatSprint: 'WetSprint', WeatComponent: 'WetComponent'}
if (!kinds[assocTypeEnumId]) { ec.message.addError(ec.resource.expand('${assocTypeEnumId} is not a kind of plan item', '', {assocTypeEnumId})); return }
const task = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
if (task == null) { ec.message.addError(ec.resource.expand('Task ${workEffortId} not found', '', {workEffortId})); return }
if (planWorkEffortId) {
    const plan = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', planWorkEffortId).one()
    if (plan == null || plan.workEffortTypeEnumId !== kinds[assocTypeEnumId] || plan.rootWorkEffortId !== task.rootWorkEffortId) {
        ec.message.addError(ec.resource.expand('${planWorkEffortId} is not a plan item of the project of ${workEffortId}', '', {planWorkEffortId, workEffortId}))
        return
    }
}
let found = false
for (const assoc of ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('toWorkEffortId', workEffortId)
        .condition('workEffortAssocTypeEnumId', assocTypeEnumId).conditionDate('fromDate', 'thruDate', null).list()) {
    if (planWorkEffortId && assoc.workEffortId === planWorkEffortId) { found = true; continue }
    assoc.set('thruDate', ec.user.nowTimestamp)
    assoc.update()
}
if (!planWorkEffortId || found) return
// a membership ended in the same instant is taken up again rather than made twice
const same = ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('workEffortId', planWorkEffortId).condition('toWorkEffortId', workEffortId)
        .condition('workEffortAssocTypeEnumId', assocTypeEnumId).condition('fromDate', ec.user.nowTimestamp).one()
if (same != null) { same.set('thruDate', null); same.update(); return }
ec.service.sync().name('create#mantle.work.effort.WorkEffortAssoc').parameters({workEffortId: planWorkEffortId,
    toWorkEffortId: workEffortId, workEffortAssocTypeEnumId: assocTypeEnumId, fromDate: ec.user.nowTimestamp}).call()

changed = false
const find = (id) => id ? ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', id).one() : null
const sprint = find(sprintWorkEffortId)
if (sprintWorkEffortId) {
    if (sprint == null || sprint.workEffortTypeEnumId !== 'WetSprint') { ec.message.addError(ec.resource.expand('Sprint ${sprintWorkEffortId} not found', '', {sprintWorkEffortId})); return }
    if (['WeComplete', 'WeClosed', 'WeCancelled'].includes(sprint.statusId)) {
        ec.message.addError(ec.resource.expand('${name} is complete and takes no more items', '', {name: sprint.workEffortName || sprintWorkEffortId})); return
    }
}
const current = Array.from(ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('toWorkEffortId', workEffortId)
        .condition('workEffortAssocTypeEnumId', 'WeatSprint').conditionDate('fromDate', 'thruDate', null).list()).map((assoc) => assoc.workEffortId)
oldSprintWorkEffortId = current[0] || null
if ((sprintWorkEffortId || null) === oldSprintWorkEffortId && current.length <= 1) return
ec.service.sync().name('mantle.work.TaskServices.set#TaskPlanItem').parameters({workEffortId: workEffortId, assocTypeEnumId: 'WeatSprint',
    planWorkEffortId: sprintWorkEffortId || null}).call()
if (ec.message.hasError()) return
changed = true
// the scope changes of the sprints in progress, with who made them
const audit = (sprintId, field) => ec.service.sync().name('create#moqui.entity.EntityAuditLog').parameters({changedEntityName: 'mantle.work.effort.WorkEffortAssoc',
    changedFieldName: field, pkPrimaryValue: sprintId, pkSecondaryValue: workEffortId, pkRestCombinedValue: "workEffortAssocTypeEnumId:'WeatSprint'",
    newValueText: String(ec.user.nowTimestamp), changedDate: ec.user.nowTimestamp, changedByUserId: ec.user.userId || null}).disableAuthz().call()
for (const oldId of current) if (oldId !== sprintWorkEffortId && find(oldId)?.statusId === 'WeInProgress') audit(oldId, 'thruDate')
if (sprint != null && sprint.statusId === 'WeInProgress' && !current.includes(sprintWorkEffortId)) audit(sprintWorkEffortId, 'fromDate')

renumbered = false
const task = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
if (task == null || task.workEffortTypeEnumId !== 'WetTask' || !task.rootWorkEffortId) {
    ec.message.addError(ec.resource.expand('Task ${workEffortId} not found', '', {workEffortId})); return
}
const rankOf = (row) => row.sequenceNum == null || row.sequenceNum === '' ? null : Number(String(row.sequenceNum))
const numberOf = (id) => { const match = /(\d+)$/.exec(String(id)); return match ? Number(match[1]) : Number.MAX_SAFE_INTEGER }
const others = Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('rootWorkEffortId', task.rootWorkEffortId)
        .condition('workEffortTypeEnumId', 'WetTask').condition('workEffortId', 'not-equals', workEffortId)
        .selectField('workEffortId').selectField('sequenceNum').list()).sort((left, right) => {
    const l = rankOf(left), r = rankOf(right)
    if (l != null && r != null && l !== r) return l - r
    if (l != null && r == null) return -1
    if (l == null && r != null) return 1
    return numberOf(left.workEffortId) - numberOf(right.workEffortId) || String(left.workEffortId).localeCompare(String(right.workEffortId))
})
let index = 0
if (previousWorkEffortId) {
    const at = others.findIndex((row) => row.workEffortId === previousWorkEffortId)
    if (at < 0) { ec.message.addError(ec.resource.expand('${previousWorkEffortId} is not in the project of ${workEffortId}', '', {previousWorkEffortId, workEffortId})); return }
    index = at + 1
} else if (nextWorkEffortId) {
    const at = others.findIndex((row) => row.workEffortId === nextWorkEffortId)
    if (at < 0) { ec.message.addError(ec.resource.expand('${nextWorkEffortId} is not in the project of ${workEffortId}', '', {nextWorkEffortId, workEffortId})); return }
    index = at
}
const before = index > 0 ? rankOf(others[index - 1]) : 0
const after = index < others.length ? rankOf(others[index]) : null
const ranked = others.every((row) => rankOf(row) != null)
const set = (id, rank) => ec.service.sync().name('update#mantle.work.effort.WorkEffort').parameters({workEffortId: id, sequenceNum: rank}).call()
if (ranked && before != null && (after == null || after - before >= 2)) {
    sequenceNum = after == null ? before + 1000 : Math.floor((before + after) / 2)
    if (rankOf(task) !== sequenceNum) set(workEffortId, sequenceNum)
    return
}
// the gap is closed, or ranks are missing: number the project's tasks again in their order, with the task in its place
renumbered = true
const ordered = others.slice(0, index).concat([task], others.slice(index))
ordered.forEach((row, i) => {
    const rank = (i + 1) * 1000
    if (row.workEffortId === workEffortId) sequenceNum = rank
    if (rankOf(row) !== rank) set(row.workEffortId, rank)
})

created = false
const L = (text, values) => ec.resource.expand(ec.l10n.localize(text), '', values || {})
const one = (id) => ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', id).one()
const from = one(workEffortId)
const to = one(toWorkEffortId)
if (from == null || from.workEffortTypeEnumId !== 'WetTask') { ec.message.addError(L('Work item ${id} not found', {id: workEffortId})); return }
if (to == null || to.workEffortTypeEnumId !== 'WetTask') { ec.message.addError(L('Work item ${id} not found', {id: toWorkEffortId})); return }
if (workEffortId === toWorkEffortId) { ec.message.addError(L('A work item does not depend on itself')); return }
const lag = lagDays == null || lagDays === '' ? null : Number(String(lagDays))
if (lag != null && (!Number.isFinite(lag) || lag < 0)) { ec.message.addError(L('The lag is 0 or more working days')); return }
// an ancestor or a descendant: the parent's span already holds its sub-items
const ancestors = (row) => {
    const out = []
    let at = row
    for (let guard = 0; at && at.parentWorkEffortId && guard < 500; guard++) { out.push(at.parentWorkEffortId); at = one(at.parentWorkEffortId) }
    return out
}
if (ancestors(from).includes(toWorkEffortId) || ancestors(to).includes(workEffortId)) {
    ec.message.addError(L('${from} and ${to} are in one branch of the tree: a parent spans its sub-items', {from: workEffortId, to: toWorkEffortId})); return
}
// a loop: toWorkEffortId depends on workEffortId already, through any chain
const dependsOn = (id) => Array.from(ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('workEffortId', id)
        .condition('workEffortAssocTypeEnumId', 'WeatDependsOn').conditionDate('fromDate', 'thruDate', null).selectField('toWorkEffortId').list())
        .map((row) => row.toWorkEffortId)
const seen = new Set([toWorkEffortId])
const queue = [toWorkEffortId]
for (let i = 0; i < queue.length && i < 20000; i++) {
    for (const next of dependsOn(queue[i])) {
        if (next === workEffortId) {
            ec.message.addError(L('${to} already waits for ${from}, so ${from} cannot wait for it', {from: workEffortId, to: toWorkEffortId})); return
        }
        if (!seen.has(next)) { seen.add(next); queue.push(next) }
    }
}
const existing = Array.from(ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('workEffortId', workEffortId)
        .condition('toWorkEffortId', toWorkEffortId).condition('workEffortAssocTypeEnumId', 'WeatDependsOn')
        .conditionDate('fromDate', 'thruDate', null).list())
if (existing.length) {
    for (const row of existing) if ((row.lagDays == null ? null : Number(String(row.lagDays))) !== lag) { row.set('lagDays', lag); row.update() }
    return
}
ec.service.sync().name('create#mantle.work.effort.WorkEffortAssoc').parameters({workEffortId: workEffortId, toWorkEffortId: toWorkEffortId,
    workEffortAssocTypeEnumId: 'WeatDependsOn', fromDate: ec.user.nowTimestamp, lagDays: lag}).call()
if (!ec.message.hasError()) created = true

removed = false
for (const row of ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('workEffortId', workEffortId).condition('toWorkEffortId', toWorkEffortId)
        .condition('workEffortAssocTypeEnumId', 'WeatDependsOn').conditionDate('fromDate', 'thruDate', null).list()) {
    row.set('thruDate', ec.user.nowTimestamp)
    row.update()
    removed = true
}

movedList = []
failedList = []
const L = (text, values) => ec.resource.expand(ec.l10n.localize(text), '', values || {})
const one = (id) => ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', id).one()
const item = one(workEffortId)
if (item == null || !['WetTask', 'WetMilestone', 'WetRelease', 'WetSprint'].includes(item.workEffortTypeEnumId)) {
    ec.message.addError(L('Work item ${id} not found', {id: workEffortId})); return
}
const isDay = (text) => /^\d{4}-\d{2}-\d{2}$/.test(String(text))
if (startDay != null && startDay !== '' && !isDay(startDay)) { ec.message.addError(L('The start is a day, yyyy-MM-dd')); return }
if (dueDay != null && dueDay !== '' && !isDay(dueDay)) { ec.message.addError(L('The due date is a day, yyyy-MM-dd')); return }
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    const text = String(value)
    if (/^-?\d+$/.test(text)) return Number(text)
    const parsed = Date.parse(text)
    return Number.isNaN(parsed) ? null : parsed
}
const dayOf = (value) => toMillis(value) == null ? null : ec.l10n.format(String(toMillis(value)), 'yyyy-MM-dd')
const timeOf = (value) => toMillis(value) == null ? '00:00:00.000' : ec.l10n.format(String(toMillis(value)), 'HH:mm:ss.SSS')
const stamp = (day, old) => day ? ec.l10n.parseTimestamp(day + ' ' + timeOf(old), 'yyyy-MM-dd HH:mm:ss.SSS') : null
const addDays = (text, days) => { const d = new Date(text + 'T12:00:00Z'); d.setUTCDate(d.getUTCDate() + days); return d.toISOString().substring(0, 10) }
const daysBetween = (from, to) => Math.round((Date.parse(to + 'T12:00:00Z') - Date.parse(from + 'T12:00:00Z')) / 86400000)
const write = (row, start, due) => {
    const fields = {workEffortId: row.workEffortId}
    const oldStart = dayOf(row.estimatedStartDate)
    const oldDue = dayOf(row.estimatedCompletionDate)
    if (start !== undefined && start !== oldStart) fields.estimatedStartDate = stamp(start, row.estimatedStartDate)
    if (due !== undefined && due !== oldDue) fields.estimatedCompletionDate = stamp(due, row.estimatedCompletionDate)
    if (Object.keys(fields).length === 1) return false
    ec.service.sync().name('update#mantle.work.effort.WorkEffort').parameters(fields).call()
    if (ec.message.hasError()) return false
    movedList.push({workEffortId: row.workEffortId, startDay: start !== undefined ? start : oldStart, dueDay: due !== undefined ? due : oldDue})
    return true
}

const oldStart = dayOf(item.estimatedStartDate)
const oldDue = dayOf(item.estimatedCompletionDate)
const shiftBy = shiftDays == null || shiftDays === '' ? null : Math.round(Number(String(shiftDays)))
if (shiftBy != null && Number.isFinite(shiftBy)) {
    startDay = oldStart ? addDays(oldStart, shiftBy) : null
    dueDay = oldDue ? addDays(oldDue, shiftBy) : null
}
const newStart = startDay == null ? oldStart : (startDay === '' ? null : String(startDay))
const newDue = dueDay == null ? oldDue : (dueDay === '' ? null : String(dueDay))
if (newStart && newDue && newDue < newStart) { ec.message.addError(L('${id} is due on or after the day it starts', {id: workEffortId})); return }
write(item, startDay == null ? undefined : newStart, dueDay == null ? undefined : newDue)
if (ec.message.hasError()) return

// a summary bar moved: its sub-items by the same days
const shift = shiftBy != null && Number.isFinite(shiftBy) ? shiftBy
    : (oldStart && newStart ? daysBetween(oldStart, newStart) : (oldDue && newDue ? daysBetween(oldDue, newDue) : 0))
if (moveSubtree && shift && item.workEffortTypeEnumId === 'WetTask') {
    const queue = [workEffortId]
    for (let i = 0; i < queue.length && i < 20000; i++) {
        for (const child of ec.entity.find('mantle.work.effort.WorkEffort').condition('parentWorkEffortId', queue[i]).orderBy('workEffortId').list()) {
            queue.push(child.workEffortId)
            const childStart = dayOf(child.estimatedStartDate)
            const childDue = dayOf(child.estimatedCompletionDate)
            if (!childStart && !childDue) continue
            write(child, childStart ? addDays(childStart, shift) : undefined, childDue ? addDays(childDue, shift) : undefined)
            if (ec.message.hasError()) return
        }
    }
}
if (!autoSchedule || item.workEffortTypeEnumId !== 'WetTask') return

// the dependents, moved forward by business days
const project = item.rootWorkEffortId ? one(item.rootWorkEffortId) : null
const organizationPartyId = project?.ownerPartyId || null
const future = (day, days) => {
    if (days <= 0) return day
    const out = ec.service.sync().name('mantle.work.EventServices.get#FutureBusinessDay').parameters({startDate: day, businessDays: days,
        organizationPartyId: organizationPartyId}).call()
    // a Date comes back as yyyy-MM-dd text or as epoch millis of its UTC midnight
    const value = out?.futureDayDate
    if (value == null) return addDays(day, days)
    const text = String(value)
    return /^\d{4}-\d{2}-\d{2}/.test(text) ? text.substring(0, 10) : new Date(Number(text)).toISOString().substring(0, 10)
}
// the business days from one day to a later one (each step a next business day), at most 400
const businessLength = (from, to) => {
    let count = 0
    let at = from
    while (at < to && count < 400) { at = future(at, 1); count++ }
    return count
}
const dependentsOf = (id) => Array.from(ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('toWorkEffortId', id)
        .condition('workEffortAssocTypeEnumId', 'WeatDependsOn').conditionDate('fromDate', 'thruDate', null).list())
const dueOf = new Map([[workEffortId, newDue || newStart]])
const queue = [workEffortId]
const visits = new Map()
for (let i = 0; i < queue.length && i < 5000; i++) {
    const predecessorId = queue[i]
    const predecessorDue = dueOf.get(predecessorId)
    if (!predecessorDue) continue
    for (const link of dependentsOf(predecessorId)) {
        const dependentId = link.workEffortId
        // a loop in old data is left after a few passes
        const count = (visits.get(dependentId) || 0) + 1
        visits.set(dependentId, count)
        if (count > 20) continue
        ec.message.pushErrors()
        try {
            const dependent = one(dependentId)
            if (dependent == null || ['WeComplete', 'WeClosed', 'WeCancelled'].includes(dependent.statusId)) continue
            const lag = link.lagDays == null ? 0 : Math.max(0, Math.ceil(Number(String(link.lagDays)) || 0))
            const earliest = future(predecessorDue, 1 + lag)
            const start = dayOf(dependent.estimatedStartDate)
            const due = dayOf(dependent.estimatedCompletionDate)
            if (!start && !due) continue
            if ((start || due) >= earliest) { dueOf.set(dependentId, due || start); continue }
            let nextStart, nextDue
            if (start && due) { nextStart = earliest; nextDue = future(earliest, businessLength(start, due)) }
            else if (start) nextStart = earliest
            else nextDue = earliest
            ec.service.sync().name('mantle.work.TaskServices.set#TaskDates').parameters({workEffortId: dependentId,
                startDay: nextStart, dueDay: nextDue}).call()
            if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
            movedList.push({workEffortId: dependentId, startDay: nextStart || null, dueDay: nextDue || null})
            dueOf.set(dependentId, nextDue || nextStart)
            queue.push(dependentId)
        } catch (err) {
            const error = String(err && err.message ? err.message : err)
            ec.logger.error(`Auto-schedule after ${workEffortId}: ${dependentId} not moved: ${error}`)
            failedList.push({workEffortId: dependentId, error: error})
        } finally {
            ec.message.clearErrors()
            ec.message.popErrors()
        }
    }
}

transitionList = []
flowStatusIds = []
const task = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
if (task == null) { ec.message.addError(ec.resource.expand('Task ${workEffortId} not found', '', {workEffortId})); return }
statusId = task.statusId || null
statusFlowId = task.statusFlowId || null
if (!statusFlowId && task.rootWorkEffortId) statusFlowId = ec.entity.find('mantle.work.effort.WorkEffort')
        .condition('workEffortId', task.rootWorkEffortId).one()?.statusFlowId || null
statusFlowId = statusFlowId || 'Default'
const items = {}
const itemOf = (id) => items[id] || (items[id] = ec.entity.find('moqui.basic.StatusItem').condition('statusId', id).useCache(true).one())
const sequence = (id) => { const item = itemOf(id); return item?.sequenceNum != null ? Number(String(item.sequenceNum)) : 999 }
const all = Array.from(ec.entity.find('moqui.basic.StatusFlowTransition').condition('statusFlowId', statusFlowId).useCache(true).list())
// the Default flow holds the transitions of every status type: only the work effort statuses
const statuses = new Set()
for (const row of all) { statuses.add(row.statusId); statuses.add(row.toStatusId) }
flowStatusIds = Array.from(statuses).filter((id) => itemOf(id)?.statusTypeId === 'WorkEffort').sort((left, right) => sequence(left) - sequence(right))
transitionList = all.filter((row) => row.statusId === statusId).sort((left, right) => sequence(left.toStatusId) - sequence(right.toStatusId))
        .map((row) => ({toStatusId: row.toStatusId, transitionName: row.transitionName || null, description: itemOf(row.toStatusId)?.description || row.toStatusId}))

const fields = {workEffortId: workEffortId, statusId: statusId}
const done = ['WeComplete', 'WeClosed', 'WeCancelled']
if (statusId === 'WeComplete') Object.assign(fields, {resolutionEnumId: resolutionEnumId || 'WerCompleted', actualCompletionDate: ec.user.nowTimestamp})
else if (statusId === 'WeCancelled') fields.resolutionEnumId = resolutionEnumId || 'WerWontComplete'
else if (statusId === 'WeClosed') { if (resolutionEnumId) fields.resolutionEnumId = resolutionEnumId }
else if (done.includes(oldStatusId)) Object.assign(fields, {resolutionEnumId: 'WerUnresolved', actualCompletionDate: null})
ec.service.sync().name('mantle.work.TaskServices.update#Task').parameters(fields).call()

const find = (id) => id ? ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', id).one() : null
const task = find(workEffortId)
if (task == null || task.workEffortTypeEnumId !== 'WetTask') { ec.message.addError(ec.resource.expand('Task ${workEffortId} not found', '', {workEffortId})); return }
const parentId = parentWorkEffortId || null
if (parentId) {
    const parent = find(parentId)
    if (parent == null || parent.workEffortTypeEnumId !== 'WetTask') { ec.message.addError(ec.resource.expand('Task ${parentId} not found', '', {parentId})); return }
    if (parent.rootWorkEffortId !== task.rootWorkEffortId) {
        ec.message.addError(ec.resource.expand('${parentId} is in another project, so ${workEffortId} cannot go under it', '', {parentId, workEffortId}))
        return
    }
    // the new parent may not be the task or one of its descendants: walk up from the parent
    let at = parent
    for (let guard = 0; at != null && guard < 10000; guard++) {
        if (at.workEffortId === workEffortId) {
            ec.message.addError(ec.resource.expand('${workEffortId} cannot go under itself or one of its sub-items', '', {workEffortId}))
            return
        }
        at = find(at.parentWorkEffortId)
    }
}
if (previousSiblingId) {
    const previous = find(previousSiblingId)
    if (previous == null || previous.workEffortId === workEffortId || (previous.parentWorkEffortId || null) !== parentId
            || previous.rootWorkEffortId !== task.rootWorkEffortId) {
        ec.message.addError(ec.resource.expand('${previousSiblingId} is not under the same parent', '', {previousSiblingId}))
        return
    }
}
oldParentWorkEffortId = task.parentWorkEffortId || null
if (oldParentWorkEffortId !== parentId) {
    ec.service.sync().name('update#mantle.work.effort.WorkEffort').parameters({workEffortId: workEffortId, parentWorkEffortId: parentId}).call()
    if (ec.message.hasError()) return
    // the field's audit log (update) leaves out a first value: a move from the top level is logged here
    if (!oldParentWorkEffortId) ec.service.sync().name('create#moqui.entity.EntityAuditLog').parameters({changedEntityName: 'mantle.work.effort.WorkEffort',
        changedFieldName: 'parentWorkEffortId', pkPrimaryValue: workEffortId, newValueText: parentId, changedDate: ec.user.nowTimestamp,
        changedByUserId: ec.user.userId || null}).disableAuthz().call()
}
sequenceNum = ec.service.sync().name('mantle.work.TaskServices.set#TaskRank').parameters({workEffortId: workEffortId,
    previousSiblingId: previousSiblingId || null}).call()?.sequenceNum ?? null

renumbered = false
const task = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
if (task == null) { ec.message.addError(ec.resource.expand('Task ${workEffortId} not found', '', {workEffortId})); return }
let find = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortTypeEnumId', 'WetTask')
        .condition('workEffortId', 'not-equals', workEffortId)
find = task.parentWorkEffortId ? find.condition('parentWorkEffortId', task.parentWorkEffortId)
        : find.condition('parentWorkEffortId', 'is-null', null).condition('rootWorkEffortId', task.rootWorkEffortId)
const rankOf = (row) => row.sequenceNum == null || row.sequenceNum === '' ? null : Number(String(row.sequenceNum))
const numberOf = (id) => { const match = /(\d+)$/.exec(String(id)); return match ? Number(match[1]) : Number.MAX_SAFE_INTEGER }
const siblings = Array.from(find.selectField('workEffortId').selectField('sequenceNum').list()).sort((left, right) => {
    const l = rankOf(left), r = rankOf(right)
    if (l != null && r != null && l !== r) return l - r
    if (l != null && r == null) return -1
    if (l == null && r != null) return 1
    return numberOf(left.workEffortId) - numberOf(right.workEffortId) || String(left.workEffortId).localeCompare(String(right.workEffortId))
})
let index = 0
if (previousSiblingId) {
    const at = siblings.findIndex((row) => row.workEffortId === previousSiblingId)
    if (at < 0) { ec.message.addError(ec.resource.expand('${previousSiblingId} is not a sibling of ${workEffortId}', '', {previousSiblingId, workEffortId})); return }
    index = at + 1
}
const before = index > 0 ? rankOf(siblings[index - 1]) : 0
const after = index < siblings.length ? rankOf(siblings[index]) : null
const ranked = siblings.every((row) => rankOf(row) != null)
const set = (id, rank) => ec.service.sync().name('update#mantle.work.effort.WorkEffort').parameters({workEffortId: id, sequenceNum: rank}).call()
if (ranked && before != null && (after == null || after - before >= 2)) {
    sequenceNum = after == null ? before + 1000 : Math.floor((before + after) / 2)
    if (rankOf(task) !== sequenceNum) set(workEffortId, sequenceNum)
    return
}
// the gap is closed, or ranks are missing: number the siblings again in their order, with the task in its place
renumbered = true
const ordered = siblings.slice(0, index).concat([task], siblings.slice(index))
ordered.forEach((row, i) => {
    const rank = (i + 1) * 1000
    if (row.workEffortId === workEffortId) sequenceNum = rank
    if (rankOf(row) !== rank) set(row.workEffortId, rank)
})

const colors = ['grey', 'blue', 'indigo', 'purple', 'pink', 'red', 'orange', 'amber', 'green', 'teal', 'cyan', 'brown']
const name = String(description).trim()
if (!name) { ec.message.addError(ec.l10n.localize('A label needs a name')); return }
if (!colors.includes(colorName)) { ec.message.addError(ec.resource.expand('${colorName} is not a label color', '', {colorName})); return }
const same = ec.entity.find('mantle.work.effort.WorkEffortCategory').condition('categoryTypeEnumId', 'WcatLabel')
        .condition(ownerPartyId ? ec.entity.conditionFactory.makeCondition('ownerPartyId', 'equals', ownerPartyId) : ec.entity.conditionFactory.makeCondition('ownerPartyId', 'is-null', null))
        .condition(ec.entity.conditionFactory.makeCondition('description', 'equals', name, false, true)).count()
if (same) { ec.message.addError(ec.resource.expand('There is a label ${name} already', '', {name})); return }
workEffortCategoryId = ec.service.sync().name('create#mantle.work.effort.WorkEffortCategory').parameters({categoryTypeEnumId: 'WcatLabel',
    description: name, colorName: colorName, ownerPartyId: ownerPartyId || null}).call()?.workEffortCategoryId

const label = ec.entity.find('mantle.work.effort.WorkEffortCategory').condition('workEffortCategoryId', workEffortCategoryId).one()
if (label == null || label.categoryTypeEnumId !== 'WcatLabel') { ec.message.addError(ec.resource.expand('${workEffortCategoryId} is not a label', '', {workEffortCategoryId})); return }
const colors = ['grey', 'blue', 'indigo', 'purple', 'pink', 'red', 'orange', 'amber', 'green', 'teal', 'cyan', 'brown']
if (colorName && !colors.includes(colorName)) { ec.message.addError(ec.resource.expand('${colorName} is not a label color', '', {colorName})); return }
const name = description == null ? null : String(description).trim()
if (name === '') { ec.message.addError(ec.l10n.localize('A label needs a name')); return }
const fields = {workEffortCategoryId: workEffortCategoryId}
if (name) fields.description = name
if (colorName) fields.colorName = colorName
ec.service.sync().name('update#mantle.work.effort.WorkEffortCategory').parameters(fields).call()

const label = ec.entity.find('mantle.work.effort.WorkEffortCategory').condition('workEffortCategoryId', workEffortCategoryId).one()
if (label == null || label.categoryTypeEnumId !== 'WcatLabel') { ec.message.addError(ec.resource.expand('${workEffortCategoryId} is not a label', '', {workEffortCategoryId})); return }
itemCount = ec.entity.find('mantle.work.effort.WorkEffortCategoryAppl').condition('workEffortCategoryId', workEffortCategoryId).deleteAll()
label.delete()

itemCount = 0
if (fromCategoryId === intoCategoryId) { ec.message.addError(ec.l10n.localize('Choose two different labels')); return }
for (const id of [fromCategoryId, intoCategoryId]) {
    const label = ec.entity.find('mantle.work.effort.WorkEffortCategory').condition('workEffortCategoryId', id).one()
    if (label == null || label.categoryTypeEnumId !== 'WcatLabel') { ec.message.addError(ec.resource.expand('${id} is not a label', '', {id})); return }
}
const has = new Set(Array.from(ec.entity.find('mantle.work.effort.WorkEffortCategoryAppl').condition('workEffortCategoryId', intoCategoryId)
        .selectField('workEffortId').list()).map((row) => row.workEffortId))
for (const row of ec.entity.find('mantle.work.effort.WorkEffortCategoryAppl').condition('workEffortCategoryId', fromCategoryId).list()) {
    if (!has.has(row.workEffortId)) {
        ec.service.sync().name('create#mantle.work.effort.WorkEffortCategoryAppl').parameters({workEffortId: row.workEffortId, workEffortCategoryId: intoCategoryId}).call()
        itemCount++
    }
    row.delete()
}
ec.entity.find('mantle.work.effort.WorkEffortCategory').condition('workEffortCategoryId', fromCategoryId).one()?.delete()

const task = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
if (task == null || task.workEffortTypeEnumId !== 'WetTask') { ec.message.addError(ec.resource.expand('Task ${workEffortId} not found', '', {workEffortId})); return }
// the series: the task, or the series it was made from
seriesWorkEffortId = workEffortId
const link = Array.from(ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('toWorkEffortId', workEffortId)
        .condition('workEffortAssocTypeEnumId', 'WeatRecurrenceInstance').list())[0]
if (link && ec.entity.find('mantle.work.effort.WorkEffortRecurrence').condition('workEffortId', link.workEffortId).one() != null)
    seriesWorkEffortId = link.workEffortId
const existing = ec.entity.find('mantle.work.effort.WorkEffortRecurrence').condition('workEffortId', seriesWorkEffortId).one()
const rule = rrule == null ? '' : String(rrule).trim().replace(/^RRULE:/i, '')
if (!rule) {
    if (existing != null) existing.delete()
    return
}
if (!/(^|;)FREQ=(DAILY|WEEKLY|MONTHLY|YEARLY)(;|$)/i.test(rule)) {
    ec.message.addError(ec.resource.expand('Not a repeat rule: ${rule}', '', {rule}))
    return
}
if (task.estimatedCompletionDate == null && task.estimatedStartDate == null) {
    ec.message.addError(ec.l10n.localize('Give the work item a due date before it repeats'))
    return
}
const fields = {workEffortId: seriesWorkEffortId, rrule: rule.toUpperCase(), recurFromCompletion: recurFromCompletion === 'Y' ? 'Y' : 'N',
    timeZone: timeZone || existing?.timeZone || ec.user.timeZone || null}
ec.service.sync().name(existing != null ? 'update#mantle.work.effort.WorkEffortRecurrence' : 'create#mantle.work.effort.WorkEffortRecurrence')
        .parameters(fields).call()

newWorkEffortId = null
const task = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
if (task == null || task.workEffortTypeEnumId !== 'WetTask' || !['WeComplete', 'WeCancelled'].includes(task.statusId)) return
let seriesId = workEffortId
let recurrence = ec.entity.find('mantle.work.effort.WorkEffortRecurrence').condition('workEffortId', workEffortId).one()
if (recurrence == null) {
    const link = Array.from(ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('toWorkEffortId', workEffortId)
            .condition('workEffortAssocTypeEnumId', 'WeatRecurrenceInstance').list())[0]
    if (!link) return
    seriesId = link.workEffortId
    recurrence = ec.entity.find('mantle.work.effort.WorkEffortRecurrence').condition('workEffortId', seriesId).one()
}
if (recurrence == null || !recurrence.rrule) return
const series = seriesId === workEffortId ? task : ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', seriesId).one()
if (series == null) return
const toMillis = (value) => {
    if (value == null || value === '') return null
    const text = String(value)
    if (/^-?\d+$/.test(text)) return Number(text)
    const parsed = Date.parse(text)
    return Number.isNaN(parsed) ? null : parsed
}
const dueOf = (row) => toMillis(row.estimatedCompletionDate) ?? toMillis(row.estimatedStartDate)
const thisDue = dueOf(task)
const seriesDue = dueOf(series)
if (thisDue == null || seriesDue == null) { ec.logger.warn(`Recurring task ${workEffortId}: no due date, no next item`); return }
if (ec.factory.getToolFactory('ICalendar') == null) { ec.logger.error(`Recurring task ${workEffortId}: no ICalendar tool to expand ${recurrence.rrule}`); return }
const tool = ec.factory.getTool('ICalendar')
const zone = recurrence.timeZone || ec.user.timeZone || null
const yearMs = 366 * 86400000
let next = null
try {
    if (recurrence.recurFromCompletion === 'Y') {
        // from the day it was completed, at the due date's time of day; a COUNT counts the items made
        const doneMs = toMillis(task.actualCompletionDate) ?? toMillis(ec.user.nowTimestamp)
        const dayMs = 86400000
        // the day it was completed at the due date's time of day (UTC days)
        const startMs = doneMs - ((doneMs % dayMs) + dayMs) % dayMs + ((thisDue % dayMs) + dayMs) % dayMs
        const countMatch = /(^|;)COUNT=(\d+)/i.exec(recurrence.rrule)
        const rule = String(recurrence.rrule).split(';').filter((part) => !/^COUNT=/i.test(part)).join(';')
        if (countMatch) {
            const made = ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('workEffortId', seriesId)
                    .condition('workEffortAssocTypeEnumId', 'WeatRecurrenceInstance').count()
            if (made + 1 >= Number(countMatch[2])) return
        }
        const starts = Array.from(tool.expand(rule, startMs, zone, [], [], startMs + 1, startMs + 2 * yearMs) || []).map(toMillis)
        next = starts.find((ms) => ms != null && ms > startMs) ?? null
    } else {
        const starts = Array.from(tool.expand(String(recurrence.rrule), seriesDue, zone, [], [], thisDue + 1, thisDue + 2 * yearMs) || []).map(toMillis)
        next = starts.find((ms) => ms != null && ms > thisDue) ?? null
    }
} catch (err) {
    ec.logger.error(`Recurring task ${workEffortId}: the rule ${recurrence.rrule} was not expanded: ${err && err.message ? err.message : err}`)
    return
}
if (next == null) return
// made already (this item completed again after a reopen)
for (const link of ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('workEffortId', seriesId)
        .condition('workEffortAssocTypeEnumId', 'WeatRecurrenceInstance').list()) {
    if (toMillis(link.fromDate) === next) return
}
const startMs = toMillis(task.estimatedStartDate)
const dueMs = toMillis(task.estimatedCompletionDate)
const fields = {workEffortName: task.workEffortName, description: task.description, rootWorkEffortId: task.rootWorkEffortId,
    parentWorkEffortId: task.parentWorkEffortId, purposeEnumId: task.purposeEnumId, priority: task.priority, visibilityEnumId: task.visibilityEnumId,
    statusFlowId: task.statusFlowId, estimatedWorkTime: task.estimatedWorkTime, remainingWorkTime: task.estimatedWorkTime,
    estimatedPoints: task.estimatedPoints, totalTimeAllowed: task.totalTimeAllowed, timeUomId: task.timeUomId, ownerPartyId: task.ownerPartyId,
    statusId: 'WeInPlanning', resolutionEnumId: 'WerUnresolved', sequenceNum: task.sequenceNum}
if (dueMs != null) fields.estimatedCompletionDate = new Date(next)
if (startMs != null) fields.estimatedStartDate = new Date(dueMs != null ? next - (dueMs - startMs) : next)
newWorkEffortId = ec.service.sync().name('mantle.work.TaskServices.create#Task').parameters(fields).call()?.workEffortId || null
if (!newWorkEffortId || ec.message.hasError()) return
ec.service.sync().name('create#mantle.work.effort.WorkEffortAssoc').parameters({workEffortId: seriesId, toWorkEffortId: newWorkEffortId,
    workEffortAssocTypeEnumId: 'WeatRecurrenceInstance', fromDate: new Date(next)}).call()
// its people (assignees, team, watchers, managers; not declined), labels and component
for (const wep of ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', workEffortId)
        .conditionDate('fromDate', 'thruDate', null).list()) {
    if (['WeptDeclined', 'WeptUnassigned'].includes(wep.statusId)) continue
    ec.service.sync().name('mantle.work.WorkEffortServices.add#WorkEffortParty').parameters({workEffortId: newWorkEffortId, partyId: wep.partyId,
        roleTypeId: wep.roleTypeId, statusId: wep.statusId}).call()
}
for (const appl of ec.entity.find('mantle.work.effort.WorkEffortCategoryAppl').condition('workEffortId', workEffortId).list())
    ec.service.sync().name('create#mantle.work.effort.WorkEffortCategoryAppl').parameters({workEffortId: newWorkEffortId,
        workEffortCategoryId: appl.workEffortCategoryId}).call()
for (const assoc of ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('toWorkEffortId', workEffortId)
        .condition('workEffortAssocTypeEnumId', 'WeatComponent').conditionDate('fromDate', 'thruDate', null).list())
    ec.service.sync().name('create#mantle.work.effort.WorkEffortAssoc').parameters({workEffortId: assoc.workEffortId, toWorkEffortId: newWorkEffortId,
        workEffortAssocTypeEnumId: 'WeatComponent', fromDate: ec.user.nowTimestamp}).call()
for (const follower of ec.entity.find('mantle.party.communication.RecordFollower').condition('recordEntityName', 'mantle.work.effort.WorkEffort')
        .condition('recordId', workEffortId).list()) {
    const fields = follower.getMap()
    fields.recordId = newWorkEffortId
    ec.service.sync().name('create#mantle.party.communication.RecordFollower').parameters(fields).call()
}

try {
    const task = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
    if (task == null || task.workEffortTypeEnumId !== 'WetTask' || !task.rootWorkEffortId) return
    const userIds = Array.from(ec.entity.find('moqui.security.UserAccount').condition('partyId', partyId).selectField('userId')
            .disableAuthz().list()).map((account) => account.userId).filter((userId) => userId !== ec.user.userId)
    if (!userIds.length) return
    const project = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', task.rootWorkEffortId).one()
    const me = ec.user.userAccount?.partyId ? ec.entity.find('mantle.party.PartyDetail').condition('partyId', ec.user.userAccount.partyId).one() : null
    const assignedByName = me ? (me.organizationName || [me.firstName, me.lastName].filter((part) => part).join(' ') || me.partyId) : (ec.user.username || 'System')
    const nm = ec.makeNotificationMessage().topic('WorkItemAssigned').userIds(userIds).message({workEffortId: workEffortId,
        workEffortName: task.workEffortName || workEffortId, rootWorkEffortId: task.rootWorkEffortId,
        projectName: project?.workEffortName || task.rootWorkEffortId, assignedByName: assignedByName,
        recordEntityName: 'mantle.work.effort.WorkEffort', recordId: workEffortId})
    if (typeof nm.reasonEnumId === 'function') nm.reasonEnumId('NrAssignment')
    if (typeof nm.record === 'function') nm.record('mantle.work.effort.WorkEffort', workEffortId)
    nm.send()
} catch (err) {
    ec.logger.error(`Work item ${workEffortId} assigned to ${partyId}: notification not sent: ${err && err.message ? err.message : err}`)
}

